17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        validateRequiredFields(ownerFieldsDto);
107	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        ownerFieldsDto.setTelephone(telephone);
109	        requireUniqueTelephone(telephone);
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        this.clinicService.saveOwner(owner);
113	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
114	        headers.setLocation(UriComponentsBuilder.newInstance()
115	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
116	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
117	    }
118	
119	    /**
120	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
121	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
122	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
123	     *
124	     * @param ownerFieldsDto the owner payload to validate
125	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
126	     */
127	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
128	        List<String> missingFields = new ArrayList<>();
129	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
130	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
131	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
132	        requireText(missingFields, "city", ownerFieldsDto.getCity());
133	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
134	        if (!missingFields.isEmpty()) {
135	            throw new MissingOwnerFieldsException(missingFields);
136	        }
137	    }
138	
139	    private void requireText(List<String> missingFields, String fieldName, String value) {
140	        if (value == null || value.isBlank()) {
141	            missingFields.add(fieldName);
142	        }
143	    }
144	
145	    /**
146	     * Normalizes a telephone number by removing every non-digit character, then requires the result to be exactly ten
147	     * digits. The normalized 10-digit value is what gets stored and returned as {@code telephone}.
148	     *
149	     * @param telephone the raw telephone value from the request
150	     * @return the normalized 10-digit telephone
151	     * @throws InvalidTelephoneException if the value is not exactly ten digits after non-digit characters are stripped
152	     */
153	    private String normalizeTelephone(String telephone) {
154	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
155	        if (digits.length() != 10) {
156	            throw new InvalidTelephoneException(
157	                "telephone must contain exactly 10 digits after removing non-digit characters");
158	        }
159	        return digits;
160	    }
161	
162	    /**
163	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
164	     * telephones are normalized the same way before comparison, so the rule holds regardless of how their number was
165	     * originally formatted.
166	     *
167	     * @param telephone the normalized telephone of the owner being created
168	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
169	     */
170	    private void requireUniqueTelephone(String telephone) {
171	        boolean inUse = this.clinicService.findAllOwners().stream()
172	            .map(existing -> existing.getTelephone() == null ? "" : existing.getTelephone().replaceAll("\\D", ""))
173	            .anyMatch(telephone::equals);
174	        if (inUse) {
175	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
176	        }
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
182	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
183	        if (currentOwner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        currentOwner.setAddress(ownerFieldsDto.getAddress());
187	        currentOwner.setCity(ownerFieldsDto.getCity());
188	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
189	        currentOwner.setLastName(ownerFieldsDto.getLastName());
190	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
191	        this.clinicService.saveOwner(currentOwner);
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Transactional
197	    @Override
198	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
199	        Owner owner = this.clinicService.findOwnerById(ownerId);
200	        if (owner == null) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        this.clinicService.deleteOwner(owner);
204	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
